INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('noddy-and-the-birthday-party', 50549, '2000-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co836g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sciz3h.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Noddy and the Birthday Party', 'It''s Big-Ears'' birthday! Can you help Noddy collect things for the party? Will Noddy earn enough pocket money to buy Big-Ears a really big cake? Explore Toyland, meet your favourite characters, and take part in 10 exciting adventures. Help Noddy find the party invitations--but watch out for Bumpy Dog. Go to the Dark Wood where Sly and Gobbo have hidden all the party hats. From gathering hidden eggs in Farmer Straw''s field to jumping over rolling fruit in the market square, help Noddy get everything for Big-Ears'' Birthday party. Watch out for Sly and Gobbo, who always seem to be up to mischief, and even Master Tubby Bear, Bumpy Dog and Clockwork Mouse, who accidentally get in the way sometimes.
