INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dirt Jockey: Heavy Equipment Operator', 'Build big machine muscle as you learn to operate heavy construction equipment that looks, feels, sounds and runs just like the real thing --- from rumbling bulldozers to hard-working dump trucks and high reaching cranes. Once you train to earn your construction licenses, you can start building a huge department store. So get in gear, move dirt and haul butt. Dirt Jockey fulfills the fantasy of operating heavy equipment for kids of all ages.' FROM games WHERE igdb_id = 43738 ON CONFLICT (game_id, language_code) DO NOTHING;
