INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Postal', 'Made specifically for the Japanese market, this version of POSTAL features a complete Japanese dub and two extra levels: Akihabara and Dōtonbori (more commonly known as Tokyo and Osaka to English speakers).' FROM games WHERE igdb_id = 375569 ON CONFLICT (game_id, language_code) DO NOTHING;
