INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO My Style: Preschool', 'LEGO My Style: Preschool is an educational game for children aged 2-4 starring the animal characters from LEGO''s Duplo line of toys. There are four learning environments - math, art, music, and language - which players can visit to learn the basics of the aforementioned principles by playing simple mini-games.' FROM games WHERE igdb_id = 253104 ON CONFLICT (game_id, language_code) DO NOTHING;
