INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Artist: Polygon Studio', 'Mario Artist: Polygon Studio is an art program allowing players to construct their own 3D models and add colors and textures to them. These objects can then be inserted into pre-made movies and animations. Another notable feature is a series of microgames, believed to be the inspiration for the WarioWare series, as it includes many almost identical games. Other games allow the player to use their 3D models.' FROM games WHERE igdb_id = 73027 ON CONFLICT (game_id, language_code) DO NOTHING;
