INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Beauty and the Beast: Magical Ballroom', 'Disney''s Beauty and the Beast is a collection of mini-games for children based around the characters of the Disney animated movie of the same name. After signing in the player starts the game in the great hallway of the Beasts'' home. Bell is trying to arrange a surprise party for the Beast and this sets the background for the mini-games.' FROM games WHERE igdb_id = 57919 ON CONFLICT (game_id, language_code) DO NOTHING;
