INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swing Away Golf', 'Bring your clubs, caddy, personality and attitude as you join Joe, Rachel, Kelly, Ryan and other golf nuts in a game packed with personality. Laugh, scowl, celebrate and hang your head in defeat- you''re going to do it all. Play leisurely for fun, or rise from the amateur ranks to the official pro tour and experience real competition in story mode. Unlock courses, characters, and game modes while earning skill points, prizes, and virtual cash.' FROM games WHERE igdb_id = 43585 ON CONFLICT (game_id, language_code) DO NOTHING;
