INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 1500 Series Vol. 46: The Mahjong Ochige - Raku Jongg', 'Simple 1500 Series vol. 46: The Mahjong Ochige - Raku Jongg is mix between a mahjong (in the theme) and a tetris puzzle game. The gameplay is about using the pieces that falls from the ceiling to combine them using the mahjong rules to make them dissapear and attack the opponent.' FROM games WHERE igdb_id = 203031 ON CONFLICT (game_id, language_code) DO NOTHING;
