INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doraemon 3: Nobita no Machi SOS!', 'Doraemon 3: Nobita no Machi SOS! is an action game for the Nintendo 64. It was released only in Japan in 2000. The game is based on the Japanese manga Doraemon and has is the sequel to two N64 games, Doraemon: Nobita to Mittsu no Seireiseki and Doraemon 2: Nobita to Hikari no Shinden, all only released in Japan.' FROM games WHERE igdb_id = 3474 ON CONFLICT (game_id, language_code) DO NOTHING;
