INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tonka Space Station', 'Tonka Space Station features nine different arcade-style games, each covering a different part of life on a space station, from gathering food to fighting off rogue asteroids. Each challenge also features a different Tonka vehicle to help you complete your task, such as driving the TEV (the Tonkonium Extraction Vehicle) with the front mounted drill or speeding through space in a space ship.
