INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rameses', 'Rameses Alexander Moran is a self-proclaimed "shy, indecisive, and uncharismatic" boy living at an Irish boarding school, which he has only contempt for. He reminisces about his childhood friend Daniel Maguire in a dream as they playfully shout profanities at each other on a busy railway station platform. He awakes on his bunkbed in a four-bed dormitory.' FROM games WHERE igdb_id = 60114 ON CONFLICT (game_id, language_code) DO NOTHING;
