INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('star-wars-early-learning-activity-center', 185865, '2000-08-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4asr.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Early Learning Activity Center', 'Join Queen Amidala and Boss Nass as they lead the people of Naboo and the Gungans in a fun-filled celebration. Star Wars: Early Learning Activity Center is a playful introduction to the world of Star Wars, designed for young learners. It provides a learn through play experience in a celebratory setting, featuring open-ended and directed play set in two exciting cities. Showcase your talents in music, dance and puppetry. Improve skills in sequencing, sorting, classifying, and following directions.' FROM games WHERE igdb_id = 185865 ON CONFLICT (game_id, language_code) DO NOTHING;
