INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monkey Puncher', 'Monkey Puncher is a video game for the Game Boy Color, developed by Atelier Double, published by Taito, and released in March 2000. The game''s goal is to train a monkey to fight in organised boxing matches in order to save the main character''s father and sibling.' FROM games WHERE igdb_id = 50026 ON CONFLICT (game_id, language_code) DO NOTHING;
