INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nascar-racers', 26815, '2000-11-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7yge.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hpxla8b4ps2n6rgwhuog.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NASCAR Racers', 'Based on the Fox cartoon series of the same name, NASCAR RACERS is a glimpse of what NASCAR will be like in the future. You can choose from five different cars, each with its own abilities that increase during the course of the race including one car that becomes invincible and another that gains a huge burst of speed. After you choose the correct car for your driving style, hit one of the 20 tracks available in the game. While you''re on the track, you need to keep an eye out for the oil slicks, water puddles, and random debris that will slow down or damage your car. If the car sustains too much damage, then the race is over, for you anyway. Luckily, there is a truck to refuel and repair your vehicle. Will you be able to cross the finish line in NASCAR RACERS?' FROM games WHERE igdb_id = 26815 ON CONFLICT (game_id, language_code) DO NOTHING;
