INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nascar-arcade', 58426, '2000-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coajgy.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NASCAR Arcade', 'NASCAR Arcade is a stock car racing game and the first NASCAR game to be made for the arcades. It''s officially licensed through Electronic Arts (who had the license at the time) and is based on the 1999 Winston Cup series. There are three different race tracks to choose from each with a different difficulty level: Talladega Superspeedway, Richmond International Raceway and Watkins Glen International. A secret Team SEGA track exist too but it''s not made available until 700 races have been made on the machine. Before racing the player can choose from real life cars and drivers that all have different strengths and weaknesses. The cars included are Pontiac Grand Prix, Ford Taurus, Chevrolet Monte Carlo and Pontiac Firebird while there are more than 30 drivers to choose from.
