INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rent-A-Hero No. 1', 'Rent A Hero No. 1, a remake of the original Mega Drive game, was released for the Dreamcast in 2000. It features similar events to Rent A Hero, this time adding Rent A Hiroko, a female counterpart of Taro. The fighting engine used for the game is the same used for Sega''s Spikeout games and allows the player to receive hints via in-game email.
