INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nba-shootout-2000', 20263, '2000-01-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ptgx41v7q91yym0jlkc5.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA ShootOut 2000', 'NBA ShootOut 2000 will be the basketball game by which all past and future basketball games will be compared to because of its? incredible graphics, undaunted realism and amazingly realistic gameplay. No other game recreates the NBA like NBA ShootOut 2000. All new player graphics recreate each and every NBA player in amazing detail. Every position has been motion captured. Seven NBA players performed 300 new moves and 42 signature dunks. New Touch Shooting? let?s you control the accuracy of your shot. Incredible TV style action cameras put you in the middle of the action like never before. State of the art artificial intelligence translates into every NBA team playing exactly like their real life counterparts. If that?s not enough, you can also design your own dunk using the revolutionary Create Dunk feature.' FROM games WHERE igdb_id = 20263 ON CONFLICT (game_id, language_code) DO NOTHING;
