INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-return-of-the-incredible-machine-contraptions', 51401, '2000-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jkz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scb3bf.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Return of the Incredible Machine: Contraptions', 'Return of The Incredible Machine allows players to use unique, sometimes humorous mechanical components to construct fantastic machines that accomplish unusual tasks. Each puzzle contains a partially built machine and the extra pieces needed to complete it and accomplish the goal. The player''s job is to use the pieces in the correct way to complete the machine. As players become more familiar with the various machine parts and their functions, the puzzles become more sophisticated and challenging. This third installment of the Incredible Machine series from Sierra features improved graphics and new puzzles to challenge virtual engineers of all ages. Whirring, Boinging, Thinga-Muh-Jiggy, What-Cha-Ma-Callit, Fun! So how do you build a better thinga-muh-bob? With the completely addictive, highly original devices in the Return of The Incredible Machine: Contraptions. In a category by itself, Contraptions is like nothing you''ve ever played before. Create off-the-wall gadgets using a combination of everyday flumadiddles, doohickeys, and gigamarees, like your basic laser-activated light switch and your typical mouse-driven treadmill. So break out your lab coat because, with its spectacular 3D graphics, Contraptions is sure to bring out the wild, white-haired inventor in you!' FROM games WHERE igdb_id = 51401 ON CONFLICT (game_id, language_code) DO NOTHING;
