INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Army Men: World War', '16 missions await you and your green army as you wage war against the tan army through true world war environments including beaches, jungles, countrysides and war-torn cities. Each army man has a range of weapons to use, including pistols, flame throwers and the bazooka. You can also use heavy artillery such as tanks, jeeps and boats when normal attacks fail to breach the enemy line.' FROM games WHERE igdb_id = 201092 ON CONFLICT (game_id, language_code) DO NOTHING;
