INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NHL 2K', 'NHL 2K is a series of hockey games by Visual Concepts for the Dreamcast, PlayStation 2, Nintendo GameCube, Xbox, iPhone, Xbox 360, PlayStation 3, and the Wii. Initially discontinued after the release of NHL 2K11 in 2010, the brand was revived on mobile devices in 2014. The games are officially licensed from the National Hockey League and NHL Players Association. While its games were released on consoles, its main competition was EA Sports'' NHL video games.' FROM games WHERE igdb_id = 8839 ON CONFLICT (game_id, language_code) DO NOTHING;
