INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! Monster Capsule GB', 'Yu-Gi-Oh! Monster Capsule GB is a video game for the Game Boy Color. It has only been released in Japan. The game takes most of its inspiration from the manga''s Monster World story arc and the Capsule Monsters stories, using both Duel Monsters and Capsule Monsters.' FROM games WHERE igdb_id = 56977 ON CONFLICT (game_id, language_code) DO NOTHING;
