INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fushigi no Dungeon: Fuurai no Shiren 2 - Oni Shuurai! Shiren-jou!', 'Fushigi no Dungeon: Fuurai no Shiren 2 - Oni Shuurai! Shiren-jou! is a role-playing video game developed by Chunsoft and published by Nintendo for the Nintendo 64. It is the second main entry in the Shiren the Wanderer series, which is part of the larger Mystery Dungeon series, and was originally released in Japan on September 27, 2000. The game follows Shiren, a boy who aims to defend a village from attacking demons by building a castle; he finds building materials and other items by exploring dungeons.' FROM games WHERE igdb_id = 67376 ON CONFLICT (game_id, language_code) DO NOTHING;
