INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digimon Adventure: Anode Tamer', 'The game is based on the popular manga series Digimon, which follows the adventures of children who can gain access into the digital world and fight digital monsters there. In this game, the evil Milenniamon has kidnapped several children and is planning to take control over the Digiworld. One of the good monsters, Agumon, escaped, and transported the hero Ryou to the Digiworld. Now Ryou has to fight monsters, capture them, and assemble an army to overthrow Milenniamon and to rescue his friends.' FROM games WHERE igdb_id = 37517 ON CONFLICT (game_id, language_code) DO NOTHING;
