INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rainbow Six: Covert Ops Essentials', 'Nine all-new levels featuring never before-seen missions and gameplay; stand-alone functionality doesn''t require previous versions of Rainbow Six or Roque Spear; custom mission feature allows you to choose game type, map and difficulty; gain certificates in combat subjects including hostage negotiation, kit selection, intel photo analysis and more; learn which weapons and equipment are best in various covert situations; special bonus section: the making of Rainbow Six and Roque Spear.' FROM games WHERE igdb_id = 1845 ON CONFLICT (game_id, language_code) DO NOTHING;
