INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Combat Mission: Beyond Overlord', 'The first entry in the acclaimed Combat Mission series, Beyond Overlord is a hybrid turn-based/real-time tactical simulation which focuses on military engagements fought on the north-western European front of World War II from the days immediately following the invasion of Normandy up until the war''s end in May of 1945.' FROM games WHERE igdb_id = 646 ON CONFLICT (game_id, language_code) DO NOTHING;
