INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vampire Chronicle For Matching Service', 'Released as a mail-order game via Dreamcast Direct, this version allows players to select between four fighting styles based on each Darkstalkers game (the original, Night Warriors, Vampire Savior, Savior 2 and Hunter 2) and features an online versus mode. All characters from previous entries of the Darkstalkers series are included and playable.' FROM games WHERE igdb_id = 93310 ON CONFLICT (game_id, language_code) DO NOTHING;
