INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jeopardy! 2nd Edition', 'Take the challenge of creating questions for answers with JEOPARDY! 2ND EDITION. All of the elements from the television show are here: the Jeopardy! and Double Jeopardy! Rounds, along with the big blue board and daily doubles. All of the answers retain the difficulty found in the game show, meaning your brain will be pushed to its limit. If you''re looking for something a little different, get your hands on JEOPARDY! 2ND EDITION and take the challenge.' FROM games WHERE igdb_id = 43911 ON CONFLICT (game_id, language_code) DO NOTHING;
