INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('samba-de-amigo-ver-2000', 85768, '2000-12-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6w5p.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scnr9y.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samba de Amigo ver. 2000', 'Samba de Amigo: Ver. 2000 is an upgraded version, and it contains 14 new songs, as well as six new downloadable songs for the home version. Whereas in the original game, there were only three songs to choose in each stage, this version allows the player to choose several. "Love Love/Couples" Mode, originally available only in the home version of Samba de Amigo, is included in the arcade version of Ver. 2000. A new character named Amiga joins the cast. She is Amigo''s sister, and wields a tambourine. In the home version, a new volleyball game replaces the original minigames. Survival mode was also added, where the player must finish as many songs in a row as they can. In addition, the Challenge mode has new goals, as well as five new secret stages that are quite difficult.
