INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dioramos', 'Dioramos is a swift, battle-type board game that tells winners from losers in no delay. In this exhilarating game, the playing order changes unlimitedly with the individualistic characters, while different character and weapon combinations unleash boundless and unique battle tactics including deadly combos, counters, dodges, magic, special attacks and plunder, all guaranteeing heated battles on the board.' FROM games WHERE igdb_id = 333556 ON CONFLICT (game_id, language_code) DO NOTHING;
