INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gaia Master', 'Every one hundred years, a gnome known as Gaia Master and his floating kingdom appear in the sky. This entity regards man as mere pawns to be used in a board game akin to Parker Brothers'' Monopoly. Apparently, medieval monopoly machinations make for much mirth.' FROM games WHERE igdb_id = 59153 ON CONFLICT (game_id, language_code) DO NOTHING;
