INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battle-isle-iv-the-andosia-war', 50409, '2000-12-01', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Isle IV: The Andosia War', 'The first three games are played on a hexagonal grid for a map. Players not only control the combat units (ranging from infantry and tanks to helicopters, fighters and bombers, armored trains, surface warships and submarines, stationary gun turrets), but (especially in the later games) also many support logistics units (ammo and fuel transports, scout and radar units, road and construction vehicles, and others). Units have various weapons and can gain experience (which in later games can be transferred over in a campaign). Fuel and ammo is limited, and logistics require careful attention. Players also control buildings, where units can be repaired, and sometimes, produced. Weather conditions change, affecting unit movements (for example, a sea or river can freeze, immobilizing ships but allowing light units to move through it). Fog of war is prevalent and players have to use scouting units to gain information about the battlefield. Some of those options were added in expansions or sequels. 
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 50409 AND ge.slug = 'strategy' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 50409 AND p.igdb_id = 6 ON CONFLICT DO NOTHING;
