INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chessmaster 8000', 'The grandmaster of PC chess is back and better than ever! The revamped chess AI plays at grandmaster level, even stronger than before. New chess sets with 16-bit art looks better than ever. Improved "Natural Language Advice" help you get into the game and gets kids interested in chess. Special chess lessons by Josh Waitzkin (chess grandmaster) and Bruce Pandolfini (chess author and teacher) are also included.' FROM games WHERE igdb_id = 15881 ON CONFLICT (game_id, language_code) DO NOTHING;
