INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TimeScape: Journey to Pompeii', 'In this intense, story driven adventure, play the role of Adrian Blake and travel into the past, to the city of Pompeii, 79 A.D. In a world rich with characters and the flavor of a long forgotten era, journey along with Adrian and experience a life, long buried in history. Solve many puzzles and challenges while avoiding dangerous foes. Complete numerous side quests to accomplish your purpose. Immerse yourself in the beauty and the tragedy of a society rich with culture and ritual. Go back in time, before it’s too late…' FROM games WHERE igdb_id = 73819 ON CONFLICT (game_id, language_code) DO NOTHING;
