INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bikeflyter', 'BikeFlyter is an advertising action game, created for the Aral AG company. The player controls a fat fly which is flying down a road, and must avoid oncoming bikers. By holding the left mouse button, the player can speed up; the faster the fly is going, the more score the player receives for avoiding bikers. Each collision slows the fly down and takes away one life, and the game is over once all lives are used up.' FROM games WHERE igdb_id = 142643 ON CONFLICT (game_id, language_code) DO NOTHING;
