INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mujaffa-Spillet', 'Originally released under the name ''Perker-spillet'' in Denmark, ''Mujaffa-spillet'' is a flash game developed by Danmark Radio, offering a satirical perspective on societal stereotypes. The game places players in the role of Mujaffa, an immigrant cruising through Copenhagen''s streets in a stylish BMW to earn ''Street respect points.'' The score builds through interactions with blondes, evading the police, and collecting items like gold chains and condoms.
