INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jet Coaster Dream 2', 'A sequel to "Jet Coaster Dream", known as Coaster Works outside of Japan, "Jet Coaster Dream 2" expands the roller coaster building aspects of the first game to include more management of the park itself. The game was originally set for release in the US and Europe, but was cancelled in 2001 due to the discontinuation of the Sega Dreamcast.' FROM games WHERE igdb_id = 69383 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 69383 AND p.igdb_id = 23 ON CONFLICT DO NOTHING;
