INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I.Q Remix+: Intelligent Qube', 'The sequel to the challenging PSOne cult favorite Intelligent Qube, I.Q. REMIX + is a superior puzzle game that confronts players with a simple proposition: don''t fall off their platform. The catch, of course, is that the grid-based platform that they inhabit is populated with constantly moving blocks that must be successfully navigated to avoid being pushed off. New features over the PlayStation original include updated graphics, improved special effects, and additional game modes such as simultaneous two-person play. Released exclusively in Japan.' FROM games WHERE igdb_id = 78295 ON CONFLICT (game_id, language_code) DO NOTHING;
