INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gold Digger: The Lost Mines', 'Gold Digger ‘The Lost Mines’ is a multi-level climbing game with a unique balance between strategy and action. You move around an old gold mine, picking up and mining gold with dynamite, while avoiding different adversaries. This game is different and requires more reflex skills than Spacestation Pheta, however “thinkers” will have just as much fun solving the Gold Digger screens! There are 175 built-in screens plus an editor to create your own. Available for Macintosh and Windows.' FROM games WHERE igdb_id = 214811 ON CONFLICT (game_id, language_code) DO NOTHING;
