INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tonka Workshop', 'In the Tonka Town Workshop, players bring their own tool workbench (the play set for their computer''s keyboard) with them to get a lot of projects done, with Tonka Joe as their host. At the workshop, players would use their tools to create cool projects and as well as get jobs done.' FROM games WHERE igdb_id = 165293 ON CONFLICT (game_id, language_code) DO NOTHING;
