INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RedCat: Het Machtige Monumenten Mysterie', 'Brutus and Max have locked Big Ben, Tower Bridge, Piccadilly Circus, St Paul''s Cathedral and Buckingham Palace so no one can get in or out. They want a lot of bones and cheese, otherwise things will stay locked. In a race through the subway, RedCat must beat Brutus and Max to eventually find the keys at the stations with which he can open the locks.' FROM games WHERE igdb_id = 212752 ON CONFLICT (game_id, language_code) DO NOTHING;
