INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TRL: The Rail Loaders', 'TRL: The Rail Loaders is a 2D shoot-em-up that plays for the most part on-rails - in this case, quite literally. One or two players control two trains (in single-player mode, the other train is taken over by the AI). The trains can only move on rails; switches are used to change between rail tracks in order to avoid traps or collect power-ups.' FROM games WHERE igdb_id = 266485 ON CONFLICT (game_id, language_code) DO NOTHING;
