INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Interpol', 'Interpol is a game for two players, one controls two spies (red characters) and the other controls two police officers (blue characters). The spies are in possession of secret information and must try to leave the country with them, by air or by sea. The police officers have to stop their plan. The airport and the port are blocked by the police, and individuals interested in traveling must present a code which only the police knows.' FROM games WHERE igdb_id = 148197 ON CONFLICT (game_id, language_code) DO NOTHING;
