INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('world-destruction-league-thunder-tanks--1', 140070, '2000-09-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob5hy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar50is.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Destruction League: Thunder Tanks', 'The player must obtain "powerups" and defeat enemy vehicles, but must capture the enemy flags in order to win. However, all of the vehicles are tanks, hence its name. The game itself is short, making it quite unpopular among gamers. It was also one of the first PlayStation 2 titles to be released. It is considered a spiritual successor to the Battletanx series, since it has similar gameplay to that as well, and is made by the same company, The 3DO Company. Also a mototank from Battletanx: Global Assault can be seen in the opening title sequence, and many of the playable tanks are inspired or directly copied from Battletanx. A reversed M-80 (only in the PS1 version of Battletanx: Global Assault) can also be seen in game as the unplayable AI controlled Skorpion Bomb Tank.' FROM games WHERE igdb_id = 140070 ON CONFLICT (game_id, language_code) DO NOTHING;
