INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sports Jam', 'Sports Jam has eight competitive sports for players to master in head-to-head 2-player matches. The goal is for the player to earn the title King of Sports, and this can only be done by mastering all 12 events including Football, Baseball, Hockey, Basketball, Tennis, Soccer, Golf and Cycling.' FROM games WHERE igdb_id = 45841 ON CONFLICT (game_id, language_code) DO NOTHING;
