INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ide Yosuke no Mahjong Kazoku 2', 'One of the most popular mahjong games in Japan, Ide Yosuke no Mahjong Kazoku 2 offers more than 100,000 different tiles. Partly designed by renowned Tokyo Mahjong expert Yosuke Ide, the game also provides several different camera angles, differing AI levels of aggression, and multiple play modes. Available only for the Japanese market.' FROM games WHERE igdb_id = 319695 ON CONFLICT (game_id, language_code) DO NOTHING;
