INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Totsugeki! Pappara-tai', 'Totsugeki! Papparatai is a strategy game for the Nintendo Game Boy Color, released in Japan on March 10, 2000, by publisher J-Wing. It is a Japanese-exclusive game, meaning it was not released in North America or other regions. The game is a "shooter" or strategy genre title and can be found for sale from Japanese retro game retailers online.' FROM games WHERE igdb_id = 282680 ON CONFLICT (game_id, language_code) DO NOTHING;
