INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Crimson Spring', 'A Crimson Spring is interactive fiction in the classic style of Infocom. Using an advanced parser, the player controls the lead character through several different scenes within the super-hero genre. The player controls the actions and moral code of one such hero -- the Holy Avenger -- as he attempts to investigate the murder of his lover and partner.' FROM games WHERE igdb_id = 71436 ON CONFLICT (game_id, language_code) DO NOTHING;
