INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars Math: Jabba''s Game Galaxy', 'In Star Wars Math: Jabba''s Game Galaxy, watch your students'' brainpower grow as they face Jabba the Hutt in an age-old strategy game or play a variation of the familiar classroom game "Pig" with a classmate or a favorite character. Activities using addition, subtraction, multiplication, place value and equivalencies are included. Balanced attention to both computation and reasoning makes this a great choice.' FROM games WHERE igdb_id = 73254 ON CONFLICT (game_id, language_code) DO NOTHING;
