INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Suzu Monogatari', 'Suzu Monogatari is a card battle RPG released only in Japan by Capcom in 2000 for PlayStation. The player takes the role of a young kid named Suzumaru that after losing the 5 bells of the God is sent to the human realm to recover them, to do that he will have to go around the village talking to different people and playing card games. To get new cards and items he can fish, dig, or get them from his battles. Dogs and cats can also join Suzumaru to help look for items.' FROM games WHERE igdb_id = 66075 ON CONFLICT (game_id, language_code) DO NOTHING;
