INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lattice 200EC7', 'Lattice is a high-speed abstract rail-shooter. The player constantly moves forward at a rapid pace along straight square pathways connected by junctions. Enemies and obstacles swarm from all sides, attacking or obstructing the player, which must either shoot and destroy them or avoid them by either moving to other sides of the path or jumping over them. The player can change their path through the stage at various junctions, as well as turn around and head the opposite direction if necessary.' FROM games WHERE igdb_id = 143664 ON CONFLICT (game_id, language_code) DO NOTHING;
