INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Caves of Fear', 'Set in Montevideo, Uruguay in the year 1996, players assume the role of CIA agent Jack Armstrong tasked with stopping the terrorist organization World White Order before their chemical weapon is released into the world and "purifies" all of humanity. The players interact with the demo by performing actions highlighted with text messages appearing at the bottom of the screen, along with a subliminal voice in the background that queues to their possible decisions which can affect the narrative such as the getting the main character killed, and certain actions may lead to alternative scenes and endings.' FROM games WHERE igdb_id = 302602 ON CONFLICT (game_id, language_code) DO NOTHING;
