INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Wild Thornberrys'' Animal Adventures', 'Players join Eliza and her globetrotting family of nature documentarians as they travel to exotic locations in search of rare and endangered animals in Wild Thornberrys: Animal Adventure. Nigel has decided to highlight severely endangered animals for his next documentary so The Thornberrys will need to explore animal habitats, avoid traps and solve puzzles as they make their way through the adventure.
