INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blue''s Reading Time Activities', 'Blue''s Reading Time Activities will help young children learn to read. With this CD-ROM, kids help Blue write The Big News Gazette. Purple Kangaroo, Mailbox, Baby Bear, and new friends such as Periwinkle, are all waiting at the library. Find the missing words for Fan''s story, match up the words to the pictures in Dot''s dictionary, and more. Play all five learning activities and collect stories for the newspaper. This product strengthens word recognition, listening comprehension, and early reading skills in children ages 3 to 6.' FROM games WHERE igdb_id = 50294 ON CONFLICT (game_id, language_code) DO NOTHING;
