INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wild Wild Racing', 'It was one of the first games released on the PlayStation 2 and was released on the same day as the console in the US and Europe on October 26, 2000 and November 24, 2000 respectively. Wild Wild Racing allows players to compete in all-terrain vehicle races in various countries around the globe. There are five locations in the game: United States, India, Iceland, Mexico and Australia' FROM games WHERE igdb_id = 43562 ON CONFLICT (game_id, language_code) DO NOTHING;
