INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Real War', 'Based on the official Joint Chiefs of Staff training game developed for the U.S. military, Real War uses real-world scenarios, allowing you to play as the current U.S. military or as a terrorist army extrapolated from actual terrorist forces.
