INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mobile Suit Gundam Gihren''s Greed: Blood of Zeon', 'Blood of Zeon features a more complex political system compared to the original Gihren''s Greed. The player can now create ceasefires and treaties, and the military system now supports mobile suit upgrading and customization. The map system was also updated. Blood of Zeon also introduces mobile suits and characters from various Gundam OVAs, along with the third-party factions Titan, A.E.U.G, and the Axis.' FROM games WHERE igdb_id = 75726 ON CONFLICT (game_id, language_code) DO NOTHING;
