INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DanceDanceRevolution Kids', 'In December 2000, Konami released Dance Dance Revolution KIDS, which had a new cabinet and game specifically made for a younger audience. The game was never released outside of Japan. Today, very few of these cabinets are left.' FROM games WHERE igdb_id = 314327 ON CONFLICT (game_id, language_code) DO NOTHING;
