INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Derby Tsuku: Derby Uma wo Tsukurou!', 'Derby Tsuku: Derby Ba wo Tsukurou! (ダビつく ダービー馬をつくろう!) is an entry in Sega''s Let''s Make series for the Sega Dreamcast. It''s a horse racing simulation game.' FROM games WHERE igdb_id = 283370 ON CONFLICT (game_id, language_code) DO NOTHING;
