INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hamster Club 2', 'The second hamster breeding simulation game. In addition to the familiar "Shigecchi", cute new characters are appearing one after another. A new mini-game has been added to the new story, and it is full of fun and cuteness. Comes with a mascot doll as a first-time limited benefit.' FROM games WHERE igdb_id = 281543 ON CONFLICT (game_id, language_code) DO NOTHING;
