INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hissatsu-pachinko-boy-cr-monster-house', 281567, '2000-03-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7kwj.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hissatsu Pachinko Boy CR Monster House', 'The model includes the super popular "CR Monster House". Not only the LCD screen of the actual machine, but also the movement of the pachinko ball is realistically reproduced! There are 3 modes in total. In the "capture mode", you can set the cash rate and simulate the play at a pachinko parlor while checking the balance status, rotation speed, number of jackpots, number of reach, etc. "Tamare mode" is a mode that allows you to start digitally at any time. You can change the jackpot probability and enjoy the digital movement of the LCD screen. In the "Reach Catalog", you can see all the reach patterns of Monster House at any time.' FROM games WHERE igdb_id = 281567 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 281567 AND p.igdb_id = 22 ON CONFLICT DO NOTHING;
