INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jetfighter IV: Fortress America', 'JetFighter IV: Fortress America is a combat flight simulation that gives players the thrill of piloting billion-dollar jet fighters, delivering a heart-pounding, fevered defense of American soil. Fly as the first line of defense above one of the best known cities in the USA -- downtown San Francisco and the 50,000 square miles surrounding it are meticulously recreated in jaw-dropping detail. The enemy deserves no mercy - you''re defending American soil!' FROM games WHERE igdb_id = 74105 ON CONFLICT (game_id, language_code) DO NOTHING;
