INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fukakutei Sekai no Tantei Shinshi', 'Agyou Souma is the IDLA Class A Detective. IDLA stands for International Detective License Agency. It''s a highly respectable agency that evaluates and classifies a detective based on one''s ability as a detective, from Class A to Class F. There are only 30 Class A detective in the whole world and there are only 2 Class A detective in Japan.' FROM games WHERE igdb_id = 122877 ON CONFLICT (game_id, language_code) DO NOTHING;
