INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bouken Jidai Katsugeki: Goemon', 'Bouken Jidai Katsugeki: Goemon is a Ganbare Goemon game released for the PlayStation 2 on December 21, 2000. This is the third game in the series set in a 3D world, following Mystical Ninja Starring Goemon and Ganbare Goemon: Kuru Nara Koi! Ayashige Ikka no Kuroi Kage. Unlike most of the other games, this game departs from the quirky humor that the franchise is known for and replaces it with a more serious tone.' FROM games WHERE igdb_id = 72230 ON CONFLICT (game_id, language_code) DO NOTHING;
