INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ESPN Winter X Games Snowboarding', 'In Konami''s ESPN Winter X Games Snowboarding players can relive the popular alternative sport with detailed ESPN integration and identical courses from the 2001 season. Authentic broadcast angles, in-depth rider statistics, and 15 of the world''s best pro riders are just a few of the features at their disposal while other extras include real snowboarding gear, four true-to-life X Games events (including Super Pipe and Big Air), three different gameplay modes with support for up to five players, and a killer soundtrack that features Long Beach Dub Allstars, Primer 55, Goldfinger, and more.' FROM games WHERE igdb_id = 43373 ON CONFLICT (game_id, language_code) DO NOTHING;
