INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'M&M''s: The Lost Formulas', 'M&M''s The Lost Formulas is the first M&M''s-based video game and was released on September 28, 2000 for both Macintosh and Microsoft Windows. It was published by Simon & Schuster Interactive Productions in North America and JoWooD Productions in Europe and developed by Boston Animation. It is a Crash Bandicoot, Super Magnetic Neo & Donald Duck: Goin'' Quackers style game, and also is optionally a game which teaches math.' FROM games WHERE igdb_id = 79613 ON CONFLICT (game_id, language_code) DO NOTHING;
