INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JumpStart Artist', 'Introduce children to art fundamentals with a complete set of easy-to-use design and media tools that include 40 printable activities and 60 project starters. Your child will meet famous artists, explore artistic style, and discover different genres while learning art basics including line, shape, color, texture, and pattern. A robust art kit, with an animation feature, lets kids paint, draw, and design unique masterpieces. Encourage your budding artists while helping them meet the National Standards for the Arts.' FROM games WHERE igdb_id = 294512 ON CONFLICT (game_id, language_code) DO NOTHING;
