INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Styrlitz 2: Tango in Pampas', 'Styrlitz is a comedic point-and-click adventure game. It is a parody of the popular Soviet television series Seventeen Moments of Spring about the exploits of a Soviet spy operating in Nazi Germany under the name Max Otto von Stierlitz. This is a sequel to the 1999 game Styrlitz.
