INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('keibajou-he-gyoukou-wide', 281610, '2000-04-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7kzh.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Keibajou he Gyoukou! Wide', 'Recommended for horse racing beginners and young couples who go to the racetrack like a date! A tool that allows you to easily predict horse racing simply by entering the winning odds. If you anticipate the newly introduced wide betting ticket, the hit rate will increase further. No detailed information input. The only data required for forecasting is the winning odds displayed in newspapers and racetracks. If there is a horse that is pushed or you want to exclude from the forecast among the racehorses, you can set the evaluation and reflect it in the forecast. You can select the purchase tendency of betting tickets from the four patterns of "Random", "Solid favorite", "Aim for holes", and "Aim for large holes", and the expected results will change accordingly. Of course, it comes with a convenient help function that explains horse racing terms.' FROM games WHERE igdb_id = 281610 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 281610 AND p.igdb_id = 22 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ultimate-paintball', 49901, '2000-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8439.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scs11s.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Paintball', 'Be careful when you wade into enemy territory or they will take you out of the game in ULTIMATE PAINTBALL. To win, you must capture the enemy''s flag, and in order to accomplish this you will have drive deep into enemy territory and take out hoards of foot soldiers. Luckily, there are four different weapons to choose from that make eliminating the opposition easier. But don''t get caught-up in the shooting, or you will run out of time and your flag will be captured. Fortunately, eliminating the enemies reveals arrows that show the way to the flag. While the game starts out with one flag, there will eventually be three flags to find. Try to capture the flag without getting shot in ULTIMATE PAINTBALL.' FROM games WHERE igdb_id = 49901 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 49901 AND p.igdb_id = 22 ON CONFLICT DO NOTHING;
