INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Motocross Mania', 'Motocross Mania brings you throttle-twisting fun with tons of racing and freestyle action. Realistic environments and high-performance bikes let you ride everything from big supercross jumps to huge outdoor gaps. The riding only gets better as you progress through the game and unlock different bikes and tracks, adding to your bag of big air tricks.' FROM games WHERE igdb_id = 43771 ON CONFLICT (game_id, language_code) DO NOTHING;
