INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('austin-powers-welcome-to-my-underground-lair', 18385, '2000-09-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9856.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6kav.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Austin Powers: Welcome to My Underground Lair!', 'Fans of AUSTIN POWERS will find a lot to do in AUSTIN POWERS: Welcome to My Underground Lair. This game turns your Game Boy Color into a mini-organizer, complete with a word processor (the Evil Launch Pad), a calculator (the Frickulator), and a mockup web browser that contains facts about the popular movies. Looking for something a bit more game-related? Well, AUSTIN POWERS has those in spades, too. The largest of the games, "Kin-Evil," has Dr. Evil and Mini-Me riding their scooter through a variety of stunt-packed stages. Also available for your enjoyment are the "Mojo Maze," a takeoff on PAC-MAN, "Domination," a board game similar to OTHELLO, and finally "Rock or Paper or Scissors," which pits you against an AUSTIN POWERS character in a play of the classic game. Customize the backdrop of all this fun by choosing wallpaper, screensavers, sound effects, and more. You can also link up to play some of the games with a friend or foe using either AUSTIN POWERS: Oh Behave! or AUSTIN POWERS: Welcome to My Underground Lair.' FROM games WHERE igdb_id = 18385 ON CONFLICT (game_id, language_code) DO NOTHING;
