INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Flintstones: Bedrock Bowling', 'Prehistoric times, beware -- The Flintstones have invaded the bowling alley! Fred Flintstone, Barney Rubble, Pebbles, Bamm-Bamm, and Dino are taking advantage of a newly transformed Bedrock. That pesky alien Gazoo is always up to no good; now he''s turned the entire town into massive bowling lanes complete with obtruding hazards and lots of rock!' FROM games WHERE igdb_id = 44987 ON CONFLICT (game_id, language_code) DO NOTHING;
