INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('deer-hunter', 49896, '2000-01-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/jgj2vcn6tispqzglqjot.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deer Hunter', 'The popular pursuit of hunting comes to the portable screen in DEER HUNTER for the Game Boy Color. You play as a hunter looking to catch a nice trophy in one of four different areas using three different weapons. Hunt deer with a shotgun, a rifle, or a bow, using slightly different tactics with each. If you want to be successful, you''ll have to use real-world hunting strategies. Search for droppings or other signs of movement to find the best area to wait in. Once there, use one of an assortment of tools to help you catch your prey: mask your odor with a cover scent, use a tree stand to camouflage yourself, or lure the deer with a powerful musk, a deer call, or an antler rattle. It''s up to you to decide how to catch the deer; some methods are more efficient than others, so you''ll have to find the one that works best for you. Detailed graphics and digitized sound round out the experience for would-be hunters.' FROM games WHERE igdb_id = 49896 ON CONFLICT (game_id, language_code) DO NOTHING;
