INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('chase-h-dot-q-secret-police', 49898, '2000-06-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5v6f.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chase H.Q.: Secret Police', 'The chase is on in CHASE HQ: Secret Police for the Game Boy Color. Loosely adapted from the arcade game of the same name, CHASE HQ is a unique mix of racing and action for one or two players. In the One-Player mode, you''ll lead a handpicked team of undercover cops, each with unique talents. You''ll be shown what kind of vehicle the suspect is driving, and then you''ll hit the streets to find him. When you finally locate the perp, you''ll switch to a behind-the-vehicle view as you try to shoot or bump the criminal off the road. Once you''ve managed to lower their life-bar far enough, they''ll pull over and you''ll make the arrest. There are 10 levels of single-player action, so you''ll be plenty busy as you try to collar the criminals. You can also grab a friend to play Head-to-Head using a link cable, with one person playing the cop and the other playing the bad guy.' FROM games WHERE igdb_id = 49898 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 49898 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
