INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('powerpuff-girls-bad-mojo-jojo', 3246, '2000-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5qbe.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Powerpuff Girls: Bad Mojo Jojo', 'The Powerpuff Girls make their first appearance on the Game Boy Color with POWERPUFF GIRLS: Bad Mojo Jojo. You take the role of Blossom, who is known for her intelligence. Blossom must punch and kick her way through levels filled with puzzles that need solving, and she''s got to collect all of the icons in each level. Some of them are power-ups that allow Blossom to use an ice beam to temporarily freeze her enemies, while others are artwork that can be traded between the three POWERPUFF GIRLS games. Ultimately, Blossom must come face to face with her nemesis, Mojo Jojo. Will Blossom be able to save Townsville from certain doom? Find out by playing POWERPUFF GIRLS: Bad Mojo Jojo.' FROM games WHERE igdb_id = 3246 ON CONFLICT (game_id, language_code) DO NOTHING;
