INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-maestromusic', 306737, '2000-07-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8e61.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsv3e.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Maestromusic', 'The Maestromusic is a rhythm game that comes bundled with a conductor baton controller. In order to play the game, you have to wave the baton at the right speed and with the right amount of force in order to match the game''s desired tempo and volume for the length of a song. Depending on how accurate you are with each swing, the game will either grant or subtract points and if you run out of points, you''ll fail the song. At the end of a song, you''re ranked based on your overall accuracy. The game is divided into Rehearsal and Concert modes that each have their own sets of songs from famous composers. In each mode, you need to complete three songs before the credits will roll. Once songs are played in the main modes, you can replay them as you please in the Free Mode and also read information on each of the game''s featured composers.' FROM games WHERE igdb_id = 306737 ON CONFLICT (game_id, language_code) DO NOTHING;
