INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Menkyo wo Torou', 'Menkyo wo Torou is a driving simulator game released on Playstation. The purpose is to go to a driving school and get a driver''s license. In the course, students answer questions such as traffic regulations in the form of quizzes. Practical training for manual cars requires the operation of a half-clutch.' FROM games WHERE igdb_id = 198292 ON CONFLICT (game_id, language_code) DO NOTHING;
