INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ncaa-final-four-2001', 43715, '2000-12-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/nsgz03k9pxzkng8oqhjd.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NCAA Final Four 2001', 'NCAA FINAL FOUR 2001 has all the standard game modes including Exhibition, Season and Tournament modes, and it also tracks season stats for both players and teams. The game has almost every Division I men''s college teams and sports a fair amount of women''s squads as well. The game also features the Touch Shooting Meter, so players will have even more control over their jump shots. Quinn Buckner handles the announcing duties and the sound really manages to capture that college game feel. If you get tired of playing the computer you can always take on a friend in the versus mode and take him to school.' FROM games WHERE igdb_id = 43715 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 43715 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
