INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightmist Online', 'Nightmist is an icon/text-based MUD (Multi User Dungeon). Create a fully-customizable character with distinctive strengths and weakness. Choose from one of nine classes, each one significantly influencing how you experience the game. Form allegiances and travel expansive regions, questing for riches, priceless artifacts, and most importantly, fame.' FROM games WHERE igdb_id = 140434 ON CONFLICT (game_id, language_code) DO NOTHING;
