INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tom-and-jerry-in-mouse-attacks', 8033, '2000-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6qdg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmj2o.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom and Jerry in Mouse Attacks', 'The most beloved cat and mouse team in cartoondom is together again in TOM AND JERRY IN MOUSE ATTACKS! for the Game Boy Color. Developer NewKidCo has gone all out to ensure this platform-jumping, pie-splattering, mini-game bursting title is fit for kids of all ages. In hectic, side-scrolling mayhem, you take control of everyone''s favorite little brown mouse Jerry and work your way through five danger-filled levels in an attempt to free your kidnapped pals from the clutches of Tom. Collect as many golden items as you can as you open doors leading to a wide variety of challenging mini-games (eight to be exact). Complete slide-style puzzles, engage in a creamy pie-throwing contest (try to hit Tom in the face), and even water ski! You''ll have to climb slippery poles, crash through obstacles, and make death-defying jumps in order to gather together your friends. Be careful to avoid jumping fish and creepy spiders if you want to succeed in the frantic, quick-reflex, button-pounding platform party of TOM AND JERRY IN MOUSE ATTACKS!' FROM games WHERE igdb_id = 8033 ON CONFLICT (game_id, language_code) DO NOTHING;
